"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["52394"],{63931(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.tipo_banca_nao_encontrado_ou_inativo","status":422,"titulo":"O tipo de banca n\xe3o existe ou est\xe1 desativado"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.tipo_banca_nao_encontrado_ou_inativo","requisitos":[],"oQueAconteceu":["A etapa pode requerer bancas (`bancas`), e cada banca \xe9 de um tipo do cadastro do\\nm\xf3dulo Configura\xe7\xe3o. O pedido de defini\xe7\xe3o de etapas\\n(`PUT .../processos-seletivos/{id}/etapas`) citou, em `tipoBancaId`, um\\nidentificador que n\xe3o corresponde a nenhum tipo de banca ativo. A mensagem da resposta\\ndiz: \\"O tipo de banca indicado n\xe3o existe ou est\xe1 desativado no cadastro.\\" Ela n\xe3o repete\\no identificador enviado.","O tipo de banca \xe9 copiado por valor para a etapa, e sem ele a banca n\xe3o pode ser\\nmontada. A confer\xeancia \xe9 feita etapa por etapa, na ordem do pedido, depois da\\ndeclara\xe7\xe3o dos atos e do per\xedodo de cada etapa; a primeira banca cujo tipo n\xe3o\\n\xe9 encontrado interrompe a confer\xeancia, e a resposta traz s\xf3 esta recusa, sem\\nindicar qual \xe9 a etapa nem a banca. Nada \xe9 gravado."],"comoResolver":["Confira, no cadastro de tipos de banca do m\xf3dulo Configura\xe7\xe3o, o identificador do\\ntipo pretendido e use-o em `tipoBancaId`. Se o tipo foi desativado no cadastro e\\nainda deve existir, pe\xe7a a quem o gere que o restabele\xe7a antes de repetir a\\ndefini\xe7\xe3o das etapas."],"ondeAparece":["- Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);